                  <input type="text" data-picker-others="" hidden placeholder="Tell us what you're looking for" style={{ width: "100%", padding: "12px 14px", borderRadius: "10px", border: "1px solid rgb(230, 234, 240)", fontFamily: "var(--font-sans)", fontSize: "14px", color: "rgb(31, 36, 48)", background: "rgb(255, 255, 255)", outline: "none", boxSizing: "border-box", marginTop: "10px" }} />
